// Popover — Gtk.Popover
//
// Generated by bin/11-generate-components, which does not overwrite.
//
// It ships no template, so the markup is the one element its CSS node is, carrying what
  // Adwaita styles popover with.

import type { ReactNode } from "react"

import { cn } from "@/lib/utils"
import type { WidgetProps } from "@/lib/widget-props"
import type { PositionType } from "@/lib/enums"

export interface PopoverProps extends WidgetProps {
  className?: string
  children?: ReactNode
  /** gboolean, from Gtk.Popover */
  autohide?: boolean

  /** gboolean, from Gtk.Popover */
  cascadePopdown?: boolean

  /** Widget, from Gtk.Popover */
  child?: ReactNode

  /** Widget, from Gtk.Popover */
  defaultWidget?: ReactNode

  /** gboolean, from Gtk.Popover */
  hasArrow?: boolean

  /** gboolean, from Gtk.Popover */
  mnemonicsVisible?: boolean

  /** Gdk.Rectangle, from Gtk.Popover */
  pointingTo?: ReactNode

  /** PositionType, from Gtk.Popover */
  position?: PositionType
}

export function Popover({ className, children }: PopoverProps) {
  return (
    <div className={cn(className)}>
      {children}
    </div>
  )
}
